How can I modify the provided Swift code to add a conditional statement that checks the product availability in the given Excel table and updates the email accordingly? If the product is out of stock, the email should include an apology and a recommendation for a similar product. Here is the Excel table:
| Product  | Availability |
|----------|--------------|
| Product A| In stock     |
| Product B| Out of stock |
| Product C| In stock     |
[Swift code]
let customerName = "John Smith"
let orderNumber = "12345"
let shippingDate = "2022-01-01"
let productName = "Product A"
let myName = "Jane Doe"
var emailTemplate = """
Dear \(customerName),
Thank you for reaching out to us. We are sorry to hear that you have not received your order (\(orderNumber)) yet. We have checked the status of your order and found that it was shipped on \(shippingDate).
"""
import Foundation
let fileUrl = Bundle.main.url(forResource: "products", withExtension: "xlsx")!
do {
    let data = try Data(contentsOf: fileUrl)
    let workbook = try XLSXDocument(data: data)
    let worksheet = try workbook.first?.sheet(at: 0)
    let columnTitles = try worksheet?.row(at: 0).cells.compactMap({$0.value})
    let productNameColumn = columnTitles?.firstIndex(of: "Product")
    let availabilityColumn = columnTitles?.firstIndex(of: "Availability")
    let productNameCell = try worksheet?.filter({$0.cell(at: productNameColumn!)?.value == productName}).first?.cell(at: availabilityColumn!)
    if let availability = productNameCell?.value as? String, availability == "Out of stock" {
        emailTemplate += """
        We are sorry to inform you that the product you ordered, \(productName), is currently out of stock. However, we recommend the following similar product: Product D. If you would like to proceed with this product instead, please reply to this email and we will update your order accordingly.
        """
    } else {
        emailTemplate += """
        Your product, \(productName), is currently in stock and should be delivered soon. If you have any further questions or concerns, please do not hesitate to contact us. We appreciate your business and apologize for any inconvenience this may have caused.
        """
    }
} catch {
    print(error.localizedDescription)
}
emailTemplate += """
Best regards,
\(myName)
"""
// Send email using emailTemplate as message body.

